    (307, 'abbildungen.kongruenz_teil2', 729, 3, $auf$[{"l": "verschiebung", "t": "verschiebung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Verschiebe A(4 | −1) mit dem Vektor (−6 | 8). Erst x: 4 + (−6) = ①. Dann y: −1 + 8 = ②. Dann wird A′ mit dem Vektor (9 | −5) verschoben: x ist dann ① + 9 = ③ und y ist ② + (−5) = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Erst x, dann y."}, "o": {"werte": [-2, 7, 7, 2]}, "h": "Erste Zahl zu x, zweite Zahl zu y.", "w": "A′(−2 | 7). Danach A″(−2 + 9 | 7 − 5) = (7 | 2).", "form": "lueckenweg", "zaehlt": "nein", "r": 730}, {"l": "gegenvektor", "t": "gegenvektor", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "Ein Punkt B wurde mit dem Vektor (4 | −7) verschoben und liegt jetzt bei B′(1 | 2). Der Gegenvektor ist (① | ②). Damit kommst du zurück: B(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-4, 7, -3, 9]}, "h": "Der Gegenvektor dreht beide Vorzeichen um.", "w": "Gegenvektor (−4 | 7). Zurück: 1 − 4 = −3 und 2 + 7 = 9. Also B(−3 | 9).", "form": "umkehren", "zaehlt": "ja", "r": 731}, {"l": "verschiebung", "t": "verschiebung", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne einen Vektor (a | b), der den Punkt P(2 | −1) in das Feld links oben verschiebt: Der Bildpunkt soll eine negative x-Koordinate und eine positive y-Koordinate haben. Beide Zahlen des Vektors sollen zwischen −5 und 5 liegen.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "zwischen −5 und 5", "pruefe": ["und", [">=", "$1", -5], ["<=", "$1", 5], [">=", "$2", -5], ["<=", "$2", 5]], "hinweis": "Beide Zahlen des Vektors sollen zwischen −5 und 5 liegen."}, {"name": "Bildpunkt links der y-Achse", "pruefe": ["<", ["+", 2, "$1"], 0], "zeige": ["+", 2, "$1"], "hinweis": "Dein Bildpunkt hat die x-Koordinate {}."}, {"name": "Bildpunkt über der x-Achse", "pruefe": [">", ["+", -1, "$2"], 0], "zeige": ["+", -1, "$2"], "hinweis": "Dein Bildpunkt hat die y-Koordinate {}."}], "beispiel": [-4, 3], "gut": [[-3, 2], [-5, 5]], "gegenbeispiele": [{"werte": [-9, 3], "verletzt": "zwischen −5 und 5"}, {"werte": [-2, 3], "verletzt": "Bildpunkt links der y-Achse"}, {"werte": [-4, 1], "verletzt": "Bildpunkt über der x-Achse"}]}, "h": "Wie weit muss P mindestens nach links, wie weit mindestens nach oben?", "w": "Mehr als 2 nach links (a ist −3, −4 oder −5) und mehr als 1 nach oben (b ist 2, 3, 4 oder 5).", "form": "viele_antworten", "zaehlt": "ja", "r": 732}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 4, $auf$[{"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Spiegle P(1 | −2) am Punkt Z(5 | 1). Von P zu Z geht es ① nach rechts und ② nach oben. Denselben Weg noch einmal von Z aus: P′(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 3, 9, 4]}, "h": "Z ist die Mitte zwischen P und P′.", "w": "Von P zu Z: 4 nach rechts, 3 nach oben. Von Z aus derselbe Weg: P′(9 | 4).", "form": "lueckenweg", "zaehlt": "nein", "r": 752}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einer Punktspiegelung fällt P(−6 | 3) auf P′(2 | 3). Welche x-Koordinate hat das Zentrum Z?"}, "o": {"wert": -2}, "h": "Z liegt genau in der Mitte zwischen P und P′.", "w": "Mitte von −6 und 2: (−6 + 2) : 2 = −2.", "form": "umkehren", "zaehlt": "ja", "r": 753}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Drehe P(3 | 1) um den Ursprung um 90° nach links (gegen den Uhrzeigersinn). Bildpunkt P′(□ | □).", "schablone": "P′(□ | □)", "hinweis": "Erst x, dann y."}, "o": {"werte": [-1, 3]}, "h": "Aus (x | y) wird (−y | x).", "w": "Aus (3 | 1) wird (−1 | 3). Probe mit einer Skizze: P liegt rechts, P′ liegt oben.", "form": "anwenden", "zaehlt": "ja", "r": 754}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Bei einer Punktspiegelung am Zentrum Z(a | b) fällt der Punkt P(x | y) auf P′(4 | 0). Nenne Z und P so, dass P im Feld links unten liegt (beide Koordinaten negativ). Reihenfolge der Felder: a, b, x, y.", "felder": [{"art": "rational"}, {"art": "rational"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "P links unten", "pruefe": ["und", ["<", "$3", 0], ["<", "$4", 0]], "hinweis": "Dein Punkt P liegt nicht im Feld links unten."}, {"name": "Z passt zu P und P′ (x-Richtung)", "pruefe": ["=", ["*", 2, "$1"], ["+", "$3", 4]], "zeige": ["/", ["+", "$3", 4], 2], "hinweis": "Die Mitte zwischen deinem P und P′ liegt bei x = {}."}, {"name": "Z passt zu P und P′ (y-Richtung)", "pruefe": ["=", ["*", 2, "$2"], "$4"], "zeige": ["/", "$4", 2], "hinweis": "Die Mitte zwischen deinem P und P′ liegt bei y = {}."}], "beispiel": [1, -1, -2, -2], "gut": [["1,5", "-0,5", -1, -1]], "gegenbeispiele": [{"werte": [1, -1, 2, -2], "verletzt": "P links unten"}, {"werte": [2, -1, -2, -2], "verletzt": "Z passt zu P und P′ (x-Richtung)"}, {"werte": [1, 1, -2, -2], "verletzt": "Z passt zu P und P′ (y-Richtung)"}]}, "h": "Wähle zuerst P. Das Zentrum liegt dann in der Mitte zwischen P und P′.", "w": "Zum Beispiel P(−2 | −2): Mitte von −2 und 4 ist 1, Mitte von −2 und 0 ist −1. Also Z(1 | −1).", "form": "viele_antworten", "zaehlt": "ja", "r": 755}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 76 then fehler := fehler || ('zusammen ' || gesamt || ' statt 76')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (4, 27, 40, 47, 48, 54, 307, 308) group by 1 order by 1;
